// Make sure one CSV text file arrived, and pass it on as "data" for Read CSV Text.
const item = $input.first();
const fail = (error) => [{ json: { ok: false, error } }];
const files = Object.entries(item.binary || {});
if (!files.length) return fail('No file was uploaded. Please choose a CSV file.');
const [prop, file] = files[0];
const name = String(file.fileName || 'upload');
if (!/\.csv$/i.test(name)) return fail('"' + name + '" is not a CSV file. Please upload a .csv file (in Excel use File > Save As > CSV UTF-8).');
const buf = await this.helpers.getBinaryDataBuffer(0, prop);
if (!buf.length) return fail('"' + name + '" is empty, so nothing was imported.');
if (buf.includes(0)) return fail('"' + name + '" is not a text file (it may be an Excel workbook renamed to .csv). Save it as CSV UTF-8 and upload it again.');
return [{ json: { ok: true, file_name: name }, binary: { data: file } }];

// Parse the CSV, match its headers to the data table, check every row and work out what to write.
const s = $('Import Settings').first().json;
const fileName = $('Check Uploaded File').first().json.file_name;
const text = String($('Read CSV Text').first().json.data ?? '').replace(/^\uFEFF/, '');
const tableName = String(s.data_table_name).trim();
const table = $('Find Data Table').all().map((i) => i.json).find((t) => t.name === tableName);
const existing = $('Load Existing Rows').all().map((i) => i.json).filter((r) => r.id !== undefined);
const zone = $now.zoneName;
const stop = (error) => [{ json: { ok: false, error } }];
const norm = (h) => String(h ?? '').replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
const list = (v) => [...new Set(String(v ?? '').split(',').map(norm).filter(Boolean))];
if (!table) return stop('The data table "' + tableName + '" was not found.');
if (text.includes('\uFFFD')) return stop('Some characters in the file could not be read. In Excel use File > Save As > CSV UTF-8, then upload it again.');

// Delimiter: the most common of comma, semicolon and tab in the header line (outside quotes).
const firstLine = text.split(/\r\n|\n|\r/)[0] || '';
const count = (ch) => { let k = 0, q = false; for (const c of firstLine) { if (c === '"') q = !q; else if (!q && c === ch) k++; } return k; };
const delim = [',', ';', '\t'].map((d) => [d, count(d)]).sort((a, b) => b[1] - a[1])[0][0];

// Split into records: quotes, "" escapes, line breaks inside quotes, CRLF, LF or CR.
const records = []; let row = [], cell = '', q = false;
for (let i = 0; i < text.length; i++) {
  const c = text[i];
  if (q) { if (c === '"') { if (text[i + 1] === '"') { cell += '"'; i++; } else q = false; } else cell += c; continue; }
  if (c === '"') q = true;
  else if (c === delim) { row.push(cell); cell = ''; }
  else if (c === '\r' || c === '\n') { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); records.push(row); row = []; cell = ''; }
  else cell += c;
}
if (q) return stop('A quoted value is never closed, so the file cannot be read safely. Nothing was imported.');
if (cell !== '' || row.length) { row.push(cell); records.push(row); }
const rows = records.map((cells, i) => ({ n: i + 1, cells })).filter((r) => r.cells.some((v) => v.trim() !== ''));
if (!rows.length) return stop('The file has no rows, so nothing was imported.');
if (rows.length === 1) return stop('The file only has a header row, so nothing was imported.');

// Match headers to table columns.
const cols = new Map(table.columns.map((c) => [norm(c.name), c]));
const origHeader = rows[0].cells.map((h) => h.trim());
const header = origHeader.map(norm);
const dup = header.filter((h, i) => h && header.indexOf(h) !== i);
if (dup.length) return stop('These columns appear more than once in the file: ' + [...new Set(dup)].join(', ') + '. Nothing was imported.');
const keyCol = cols.get(norm(s.key_column));
if (!keyCol) return stop('The key column "' + s.key_column + '" is not a column of the data table "' + table.name + '". Check Import Settings.');
const required = [...new Set([norm(keyCol.name), ...list(s.required_columns)])];
const badReq = required.filter((r) => !cols.has(r));
if (badReq.length) return stop('These required columns are not in the data table: ' + badReq.join(', ') + '. Check Import Settings.');
const missing = required.filter((r) => !header.includes(r)).map((r) => cols.get(r).name);
if (missing.length) return stop('The file is missing these required columns: ' + missing.join(', ') + '. Nothing was imported.');
const unknown = origHeader.filter((h, i) => header[i] && !cols.has(header[i]));
const mapped = header.map((h) => (h ? cols.get(h) || null : null));

// Convert one cell to the column's type.
const emailCols = new Set(list(s.email_columns));
const formats = String(s.date_formats || 'yyyy-MM-dd').split(',').map((f) => f.trim()).filter(Boolean);
const convert = (col, raw) => {
  const v = String(raw ?? '').trim();
  if (v === '') return { value: null };
  if (emailCols.has(norm(col.name))) { const e = v.toLowerCase(); return /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(e) ? { value: e } : { error: '"' + v + '" is not a valid email' }; }
  if (col.type === 'number') {
    let t = v.replace(/\s/g, '');
    if (delim === ';' && /^[-+]?\d+,\d+$/.test(t)) t = t.replace(',', '.');
    else if (/^[-+]?\d{1,3}(,\d{3})+(\.\d+)?$/.test(t)) t = t.replace(/,/g, '');
    return /^[-+]?(\d+\.?\d*|\.\d+)$/.test(t) ? { value: Number(t) } : { error: '"' + v + '" is not a number' };
  }
  if (col.type === 'boolean') {
    const b = v.toLowerCase();
    if (['true', 'yes', 'y', '1'].includes(b)) return { value: true };
    if (['false', 'no', 'n', '0'].includes(b)) return { value: false };
    return { error: '"' + v + '" is not true or false' };
  }
  if (col.type === 'date') {
    for (const f of formats) { const d = DateTime.fromFormat(v, f, { zone }); if (d.isValid) return { value: d.toUTC().toISO() }; }
    const d = DateTime.fromISO(v, { zone });
    return d.isValid ? { value: d.toUTC().toISO() } : { error: '"' + v + '" is not a date in the format ' + formats.join(' or ') };
  }
  return { value: v };
};
const same = (col, a, b) => {
  const empty = (x) => x === null || x === undefined || x === '';
  if (empty(a) || empty(b)) return empty(a) && empty(b);
  if (col.type === 'date') return new Date(a).getTime() === new Date(b).getTime();
  if (col.type === 'number') return Number(a) === Number(b);
  if (col.type === 'boolean') return Boolean(a) === Boolean(b);
  return String(a) === String(b);
};

// Existing rows by key, then check and classify every data row.
// Email keys match ignoring case; the stored spelling is kept as the match value so the row is updated, not duplicated.
const keyIsEmail = emailCols.has(norm(keyCol.name));
const keyOf = (v) => (keyIsEmail ? String(v).trim().toLowerCase() : String(v));
const byKey = new Map();
for (const r of existing) { const k = r[keyCol.name]; if (k !== null && k !== undefined && !byKey.has(keyOf(k))) byKey.set(keyOf(k), r); }
const csvName = origHeader.map((h, i) => (h || 'column_' + (i + 1)));
const rejected = [], toWrite = [], matchKeys = [], seen = new Map();
let inserts = 0, updates = 0, unchanged = 0;
for (const r of rows.slice(1)) {
  const reasons = [], out = {};
  if (r.cells.length < header.length || (r.cells.length > header.length && r.cells.slice(header.length).some((v) => v.trim() !== ''))) reasons.push('has ' + r.cells.length + ' values but the header has ' + header.length + ' columns');
  mapped.forEach((col, i) => { if (!col) return; const c = convert(col, r.cells[i]); if (c.error) reasons.push(col.name + ': ' + c.error); else out[col.name] = c.value; });
  for (const req of required) { const col = cols.get(req); if (out[col.name] === null) reasons.push(col.name + ' is empty'); }
  const k = keyOf(out[keyCol.name]);
  if (!reasons.length && seen.has(k)) reasons.push('same ' + keyCol.name + ' as row ' + seen.get(k));
  if (reasons.length) {
    const rec = { csv_row: r.n, rejected_reason: reasons.join('; ') };
    csvName.forEach((h, i) => { rec[h] = r.cells[i] ?? ''; });
    rejected.push(rec); continue;
  }
  seen.set(k, r.n);
  const old = byKey.get(k);
  if (!old) { inserts++; toWrite.push(out); matchKeys.push(out[keyCol.name]); }
  else if (Object.keys(out).every((c) => same(cols.get(norm(c)), out[c], old[c]))) unchanged++;
  else { updates++; toWrite.push(out); matchKeys.push(old[keyCol.name]); }
}
return [{ json: { ok: true, table: table.name, key_column: keyCol.name, file_name: fileName, delimiter: delim === '\t' ? 'tab' : delim, total: rows.length - 1, inserts, updates, unchanged, rejected_count: rejected.length, unknown_columns: unknown, to_write: toWrite, match_keys: matchKeys, rejected } }];

// Count what was written and build the result page text and the owner email.
const p = $('Parse and Check Rows').first().json;
const s = $('Import Settings').first().json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const wrote = $('Upsert Rows').isExecuted ? $('Upsert Rows').all().map((i) => i.json) : [];
const written = wrote.filter((r) => r.id !== undefined && r.id !== null).length;
const writeFailed = p.to_write.length > 0 && written < p.to_write.length;
const counts = p.inserts + ' inserted, ' + p.updates + ' updated, ' + p.unchanged + ' unchanged, ' + p.rejected_count + ' rejected';
let page = (writeFailed ? 'Writing to the data table failed, so some or all rows were not saved. Open this execution in n8n to see the error, then upload the same file again. Planned: ' : '') + counts + ' (' + p.total + (p.total === 1 ? ' row' : ' rows') + ' in ' + p.file_name + ', table ' + p.table + ').';
if (p.unknown_columns.length) page += ' These columns are not in the table and were ignored: ' + p.unknown_columns.join(', ') + '.';
const reasons = p.rejected.slice(0, 10).map((r) => '<li>Row ' + r.csv_row + ': ' + esc(r.rejected_reason) + '</li>').join('');
const html = '<p>' + p.rejected_count + ' of ' + p.total + ' rows in <b>' + esc(p.file_name) + '</b> were not imported into the data table <b>' + esc(p.table) + '</b>. The attached rejected-rows.csv lists each one with the reason. Fix them and upload the file again; rows already imported are not duplicated.</p>'
  + '<p>Result: ' + esc(counts) + '.' + (writeFailed ? ' <b>Writing to the data table failed</b>, so some or all valid rows were not saved either. Open this execution in n8n to see the error.' : '') + '</p>'
  + (p.unknown_columns.length ? '<p>Ignored columns (not in the table): ' + esc(p.unknown_columns.join(', ')) + '</p>' : '')
  + '<ul>' + reasons + '</ul>' + (p.rejected_count > 10 ? '<p>The first 10 reasons are shown; the attachment has all of them.</p>' : '');
return [{ json: { ...p, to_write: undefined, match_keys: undefined, written, write_failed: writeFailed, page_message: page, email_html: html, owner_email: s.owner_email } }];
